<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { VEHICLE_STATUSES, VEHICLE_TYPES, ENERGY_TYPES, shanghaiDateTime, type FleetOverview } from "@vectra/shared";
import { api } from "../api";
import { portalSession } from "../portal";
function companyUrl(id:string){const entry=portalSession.value?.companyLinks?.find(link=>link.id===id||link.id==="companies");return entry?.url?new URL("/carriers",entry.url).toString():"#";}
import RoadMultiSelect from "../components/RoadMultiSelect.vue";
import ParkSettingsPanel from "../components/ParkSettingsPanel.vue";
const data = ref<FleetOverview>(), busy = ref(false), message = ref(""), search = ref(""), carrier = ref(""), status = ref(""), roads = ref<string[]>([]), page = ref(1);
const carrierName = (id: string) => data.value?.settings.carriers.find(c => c.id === id)?.name ?? "所属承运商待核对";
const all = computed(() => data.value?.vehicles ?? []);
const totals = computed(() => ({ total: all.value.length, profiled: all.value.filter(v => v.profiled).length, queued: all.value.filter(v => v.status === "queued").length, inside: all.value.filter(v => ["in_park", "working", "work_completed"].includes(v.status)).length }));
const filtered = computed(() => all.value.filter(v => (!carrier.value || v.carrierId === carrier.value) && (!status.value || v.status === status.value) && (!roads.value.length || (v.lastVisit ? roads.value.includes(v.lastVisit.road) : v.allowedRoads.some(road => roads.value.includes(road)))) && (!search.value.trim() || `${v.vehicleId} ${v.plateNumber ?? ''} ${carrierName(v.carrierId)}`.toLowerCase().includes(search.value.trim().toLowerCase()))));
const pageSize = 20, pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / pageSize))), rows = computed(() => filtered.value.slice((Math.min(page.value, pages.value) - 1) * pageSize, Math.min(page.value, pages.value) * pageSize));
async function load() { busy.value = true; message.value = ""; try { data.value = await api<FleetOverview>("/api/fleet"); } catch (cause) { message.value = String(cause); } finally { busy.value = false; } }
onMounted(load);
</script>
<template>
  <section class="fleet-page"><div class="fleet-heading"><div><span class="fleet-eyebrow">车辆运行概览</span><h1>园区车辆</h1><p>查看园区车辆归属、最新车次与作业状态。</p></div><div class="button-row"><UiButton class="secondary" :disabled="busy" @click="load">{{ busy ? '刷新中…' : '刷新车辆情况' }}</UiButton><a v-for="link in portalSession?.companyLinks?.filter(item => item.url)" :key="link.id" class="text-button" :href="companyUrl(link.id)" target="_blank" rel="noopener">{{ link.name }} ↗</a><RouterLink v-if="portalSession?.legacy" class="fleet-primary-link" :to="{ path: '/carriers', query: { tab: 'vehicles' } }">进入承运商工作台 ↗</RouterLink></div></div>
    <UiAlert v-if="message" class="fleet-feedback" role="alert">{{ message }}</UiAlert><template v-if="data"><div class="fleet-metrics"><div><small>已识别车辆</small><strong>{{ totals.total }}<span>辆</span></strong><p>车辆档案及车次中的去重车辆</p></div><div><small>已完善车辆档案</small><strong>{{ totals.profiled }}<span>辆</span></strong><p>以车牌唯一识别车辆，车型等资料按需维护</p></div><div><small>排队待入园</small><strong>{{ totals.queued }}<span>辆</span></strong><p>最新车次尚无入园事件</p></div><div><small>记录显示在园</small><strong>{{ totals.inside }}<span>辆</span></strong><p>有入园或作业事件，未记录离园</p></div></div>
      <div class="fleet-snapshot-note"><i></i><span>车次快照更新于 {{ shanghaiDateTime(data.parkUpdatedAt) }}；车辆档案更新于 {{ shanghaiDateTime(data.updatedAt) }}。状态依据最近导入记录，未连接实时定位。</span></div>
      <section class="fleet-panel"><div class="fleet-panel-heading"><h2>筛选车辆</h2><span>{{ filtered.length }} 辆符合条件</span></div><div class="fleet-filter-row"><label>查找车辆<UiInput v-model="search" placeholder="车牌号或承运商名称" @input="page = 1" /></label><label>所属承运商<UiSelect v-model="carrier" @change="page = 1"><option value="">全部承运商</option><option v-for="c in data.settings.carriers" :key="c.id" :value="c.id">{{ c.name }}</option></UiSelect></label><label>当前状态<UiSelect v-model="status" @change="page = 1"><option value="">全部状态</option><option v-for="(label, key) in VEHICLE_STATUSES" :key="key" :value="key">{{ label }}</option></UiSelect></label></div><RoadMultiSelect v-model="roads" :options="data.roads" hint="不勾选时显示全部。按最新车次入口筛选；暂无车次时按车辆登记道路匹配。" @update:model-value="page = 1" /></section>
      <section class="fleet-panel fleet-table-panel"><div class="fleet-panel-heading"><div><h2>车辆明细</h2><p>车辆与车次分别管理，建档本身不代表车辆已经到园。</p></div><span class="muted">车次由各企业在独立企业端登记</span></div><UiTable v-if="rows.length" class="fleet-table"><thead><tr><th>车辆</th><th>承运商</th><th>车型 / 动力</th><th>状态</th><th>入口</th><th>最新事件（上海）</th><th>档案</th></tr></thead><tbody><tr v-for="vehicle in rows" :key="vehicle.vehicleId"><td><strong>{{ vehicle.plateNumber || '待补录车牌' }}</strong></td><td><span class="carrier-pill" :class="vehicle.carrierId">{{ carrierName(vehicle.carrierId) }}</span></td><td>{{ vehicle.vehicleType ? VEHICLE_TYPES[vehicle.vehicleType] : '车型未提供' }}<small>{{ vehicle.energyType ? ENERGY_TYPES[vehicle.energyType] : '动力未提供' }}</small></td><td><UiTag class="vehicle-status" :class="vehicle.status">{{ VEHICLE_STATUSES[vehicle.status] }}</UiTag></td><td>{{ vehicle.lastVisit?.road || vehicle.allowedRoads.join('、') || '未登记' }}<small>{{ vehicle.lastVisit ? '最新车次入口' : '登记通行入口' }}</small></td><td>{{ vehicle.lastVisit?.stage || '暂无车次事件' }}<small v-if="vehicle.lastVisit">{{ shanghaiDateTime(vehicle.lastVisit.lastEventAt) }}</small></td><td><a v-if="!portalSession?.legacy" :href="companyUrl(vehicle.carrierId)" target="_blank" rel="noopener">{{ vehicle.profiled ? '已有档案 · 企业端 ↗' : '由所属企业补充 ↗' }}</a><RouterLink v-else :to="{ path: '/carriers', query: { tab: 'vehicles', carrierId: vehicle.carrierId, vehicleId: vehicle.vehicleId } }" :class="vehicle.profiled ? 'fleet-complete' : 'fleet-incomplete'">{{ vehicle.profiled ? '查看档案 ↗' : '完善档案 ↗' }}</RouterLink></td></tr></tbody></UiTable><div v-else class="fleet-empty"><strong>{{ all.length ? '没有符合条件的车辆' : '尚无车辆资料' }}</strong><p>{{ all.length ? '调整承运商、状态或道路筛选后再查看。' : '前往承运商工作台建档，或导入真实车次识别车辆。' }}</p><RouterLink v-if="!all.length && portalSession?.legacy" :to="{ path: '/carriers', query: { tab: 'vehicles' } }">开始添加车辆 ↗</RouterLink></div><div class="fleet-pagination"><span>共 {{ filtered.length }} 辆 · 每页 {{ pageSize }} 辆</span><div><UiButton :disabled="page <= 1" @click="page--">上一页</UiButton><span>{{ Math.min(page, pages) }} / {{ pages }}</span><UiButton :disabled="page >= pages" @click="page++">下一页</UiButton></div></div></section>
    </template><p v-else-if="busy" class="fleet-loading" role="status">正在读取车辆档案与最新车次…</p>
    <ParkSettingsPanel @saved="load" />
  </section>
</template>
